import{_ as o,o as e,c as a,a2 as u}from"./chunks/framework.Crpw6aS5.js";const n=JSON.parse('{"title":"1989年 · 资本帝国的二十五载","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1989年.md","filePath":"05_quotes/by-year/1989年.md"}'),l={name:"05_quotes/by-year/1989年.md"};function r(q,t,c,s,p,i){return e(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="_1989年-·-资本帝国的二十五载" tabindex="-1">1989年 · 资本帝国的二十五载 <a class="header-anchor" href="#_1989年-·-资本帝国的二十五载" aria-label="Permalink to &quot;1989年 · 资本帝国的二十五载&quot;">​</a></h1><blockquote><p>&quot;好骑师骑好马才能赢，骑破马赢不了。有些船天生漏水比别的多，你换不了船，你能做就是调整漏水速度。&quot;——巴菲特（59岁）</p></blockquote><p>本页收录1989年致股东信中的经典语录。巴菲特在这一年庆祝了执掌伯克希尔二十五周年，坦诚复盘了二十五年来的重大错误，并系统阐述了&quot;透视盈利&quot;理念和长期持有的税收优势。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;有限世界里，高增长率必然自我毁灭，基数小的时候这个法则暂时不生效，基数balloon了，派对就结束了。卡尔·萨根说过，细菌每十五分钟分裂一倍，两天后后代总重量比太阳还重，所以指数增长不可能一直，总有障碍。&quot;</p></blockquote><blockquote><p>&quot;我们大部分持仓，我们还是会继续拿着，不管价格相对于内在价值怎么样，我们就是&#39;至死不渝&#39;态度。&quot;</p></blockquote><blockquote><p>&quot;过去我们业绩吃到了double dip：(1) portfolio公司内在价值增长；(2) 市场后来正确定价，纠正之前错误低价，给我们额外bonus。未来我们只能拿到single dip，业务增长本身，定价correction已经做完了。&quot;</p></blockquote><blockquote><p>&quot;我第一个错误就是买伯克希尔控制权，我那时候就知道纺织行业没前途，但是价格便宜我就买了。烟蒂投资方法，一开始便宜价格买，一般都会有个反弹，但好business买便宜都不一定好，如果你买了烂business，你就麻烦。&quot;</p></blockquote><blockquote><p>&quot;好骑师骑好马才能赢，骑破马赢不了。还有，institutional imperative这个看不见的力量太重要了，原来，机构惯性就是，企业就像牛顿第一运动定律，原来方向一直不变。&quot;</p></blockquote><blockquote><p>&quot;我们总结，我就是发现，和你喜欢信任欣赏的人做生意，才能成大事，你不可能和坏人做成好事。这个政策本身不能保证成功，但是没有这个政策，肯定成不了。&quot;</p></blockquote><blockquote><p>&quot;错过大机会比做错事亏大钱，伤害还大。但是错过错了没办法，你能力圈外面，你没办法，没办法就是没办法。&quot;</p></blockquote><blockquote><p>&quot;我们一直保守财务政策，我们知道，高杠杆收益高，但是一旦错了你就没了，小概率的灾难你也不能去赌。我年轻也知道，这个错误对不对，现在我还是觉得我们对。&quot;</p></blockquote><blockquote><p>&quot;想象伯克希尔只有一块钱买了一个证券，每年翻倍，二十年之后卖，变成一百万，卖了之后交税34%，剩下六十八万多；如果每年卖了再买，每次翻倍都交税，二十年之后你拿到两万五千多，政府拿走差这么多。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1989年伯克希尔净值增长15.15亿美元，增幅44.4%，是历史最高年份之一，过去二十五年复合增长率23.8%。巴菲特在这封二十五周年信中首次大幅增持可口可乐至2335万股（成本逾10亿美元），并买入吉列、美国航空、冠军国际的可转换优先股。巴菲特发行了9亿美元零息可转换债券用于融资。年底96岁的B夫人因与家族意见分歧退休，另开地毯店继续创业。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1989年/翻译.html">01_letters/1989年/翻译</a> · <a href="/01_letters/1989年/核心总结.html">01_letters/1989年/核心总结</a> · <a href="/01_letters/1989年/思维导图.html">01_letters/1989年/思维导图</a></p>',20)])])}const _=o(l,[["render",r]]);export{n as __pageData,_ as default};
